// Members page visual baselines (#181): every viewport × theme project (360/768/1280, light and
// dark) with the clock frozen: the seeded list (cards, table, table plus Roles panel), the empty
// state of a new workspace, the invite dialog open and (#288) the pending invitations tab and the
// seat summary. `Last active` comes from real sign-in sessions, so those cells are masked.
// Baselines live in e2e/__screenshots__ and are only ever generated by the e2e workflow's
// `update_snapshots` dispatch in the pinned Playwright image (see e2e/README.md); without one the
// test is skipped.
import { existsSync } from 'node:fs';

import type { Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

async function snap(page: Page, name: string) {
  await expect(page).toHaveScreenshot(name, {
    animations: 'disabled',
    caret: 'hide',
    mask: [page.locator('[data-col="last-active"]')],
  });
}

interface Shot {
  name: string;
  /** Puts the page in the state to capture. */
  setUp: (page: Page, asUser: AsUser) => Promise<void>;
}

async function openMembers(page: Page, asUser: AsUser) {
  await asUser('owner', { path: 'settings/members' });
  // The first render after a cold sign-in can take longer than the 5 s default on a loaded runner
  // (#1085, #1076 left the heading unchanged: it failed only as "not found yet", then passed).
  await expect(page.getByRole('heading', { level: 1, name: 'Members' })).toBeVisible({
    timeout: 20_000,
  });
  await shellReady(page);
}

const SHOTS: readonly Shot[] = [
  { name: 'members-list.png', setUp: openMembers },
  {
    name: 'members-invite-open.png',
    setUp: async (page, asUser) => {
      await openMembers(page, asUser);
      await page.getByRole('button', { name: 'Invite member' }).locator('visible=true').click();
      await expect(page.getByRole('dialog', { name: 'Invite members' })).toBeVisible();
    },
  },
  {
    name: 'members-invitations.png',
    setUp: async (page, asUser) => {
      await openMembers(page, asUser);
      await page.getByRole('tab', { name: /^Pending invitations/ }).click();
      await expect(page.locator('[data-status="invited"]').locator('visible=true')).toHaveCount(1);
    },
  },
  {
    name: 'members-seat-summary.png',
    setUp: async (page, asUser) => {
      await openMembers(page, asUser);
      await expect(page.locator('[data-slot="seat-summary"]')).toBeVisible();
      await page.locator('[data-slot="seat-summary"]').scrollIntoViewIfNeeded();
    },
  },
  {
    name: 'members-empty.png',
    setUp: async (page, asUser) => {
      await asUser('viewer');
      await page.goto('/onboarding/solo/workspace');
      await page.getByRole('textbox', { name: /Workspace name/ }).fill('Visual Members');
      await page.getByRole('button', { name: 'Create workspace' }).click();
      await expect(page).toHaveURL(/\/onboarding\/solo\/profile\?w=visual-members$/);
      await page.goto('/w/visual-members/settings/members');
      await expect(page.getByText(/It is just you for now/)).toBeVisible();
      await shellReady(page);
    },
  },
];

test.describe('members visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser }, testInfo) => {
        skipWithoutBaseline(testInfo, shot.name);
        await shot.setUp(page, asUser);
        await snap(page, shot.name);
      },
    );
  }
});
